const STORY={"1": {"role": "斯蒂芬", "portrait": "mulligan", "speaker": "穆利根", "title": "剃须碗里的晨光", "context": "海风从塔沿掠过。穆利根举起剃须碗，日常动作被他做成一场仪式。你听见他的玩笑，也听见自己未曾说出口的抵触。", "line": "你怎么又站在那边？过来，早饭可不等人。", "choices": ["先听清他的玩笑", "看一眼早餐与钥匙"], "feedback": "你没有把沉默解释给别人。诙谐的表面与自己的不自在，暂且放在同一页。", "aftermath": "早餐不是重归于好的证明。钥匙、房钱与彼此的姿态，让这座塔显出并非真正属于你的意味。", "kind": "objects", "items": ["剃须碗", "早餐桌", "钥匙"], "outro": "离开塔楼，去学校上课。这里的沉默会跟着你，但不会替你回答学生的问题。"}, "2": {"role": "斯蒂芬", "portrait": "deasy", "speaker": "迪希", "title": "薪资与托付", "context": "学生散去后，教室里的声响慢慢平息。你还有薪资要领，校长却另有一封信，希望你带到报馆。", "line": "你认得报馆的人，把这封信带去。这里的事情值得让他们知道。", "choices": ["先弄清信要交给谁", "将薪资与委托分开记下"], "feedback": "你记下了实际委托，没有把写信人的全部判断一并接受。", "aftermath": "钱袋与信封在同一张桌上，却不属于同一种交换。校长的强烈立场留在他的名下；接下一封信不等于替他担保一切。", "kind": "objects", "items": ["薪资", "校长的信", "课堂的余音"], "outro": "你没有立刻赶往报馆。路先通向海岸，信随后才会抵达它的下一处位置。"}, "3": {"role": "斯蒂芬", "portrait": null, "speaker": "斯蒂芬", "title": "闭眼以后", "context": "海岸没有整齐的路。脚下的沙、贝壳与潮水交替发声。闭眼的一瞬，世界并未消失，只换了一种抵达你的方式。", "line": "脚步还在。眼前没看见的东西，也在给我边界。", "choices": ["听脚底的沙与碎壳", "看潮线旁的海藻"], "feedback": "声音与可见物各留下一条线索；你的联想不必向第二个人解释。", "aftermath": "你取出信纸，在空白处写字。信件原先承担的委托没有消失，纸的另一面却容纳了此刻的语言。", "kind": "sound", "items": ["脚步", "潮水", "风声"], "outro": "同一天的清晨，另一间屋里，布卢姆正在准备早餐。此处换角，也回拨时间。"}, "4": {"role": "布卢姆", "portrait": "molly", "speaker": "摩莉", "title": "厨房里的一只猫", "context": "回到同日早晨。猫挨近脚边，炉火与器皿都有自己的次序。你先是过日子的人，然后才是这一天的主人公。", "line": "茶放在那里。你出去的时候，记着把门带好。", "choices": ["先照看猫与炉火", "留意托盘上的早饭"], "feedback": "小小的动作连成了早餐。摩莉的现场话语留在这里，她未说出口的想法并不向你开放。", "aftermath": "食物的气味把念头带向别处，手却仍在处理眼前的事。你出门买食物，再回到家庭的秩序里。", "kind": "objects", "items": ["猫的奶碟", "茶壶", "早餐托盘"], "outro": "离开家，转入街道。接下来是邮局、药房，以及不能公开给旁人看的信。"}, "5": {"role": "布卢姆", "portrait": null, "speaker": "布卢姆", "title": "一封用别名领取的信", "context": "在公共街道上，每个人都看似有一件寻常事。你取到的信却属于另一层生活，称呼与礼貌之间藏着不愿公开的部分。", "line": "把信收好。街上随便碰见一个熟人，谈话就会换个方向。", "choices": ["先读自己的信", "先留意街头的往来"], "feedback": "公开的问候继续，私人的文字被收起；两者没有合并成所有人的共同知识。", "aftermath": "药房里的木柜、气味与肥皂是可触的现实。随后出现的身体想象，仍须同已经发生的动作分开。", "kind": "objects", "items": ["私人信件", "黄色肥皂", "药房柜台"], "outro": "日常事务暂告一段落，下一站是送葬。不要把还未发生的预想画成街上的实景。"}, "6": {"role": "布卢姆", "portrait": null, "speaker": "布卢姆", "title": "马车里各自的心事", "context": "你坐在原有送葬乘员之中。车窗外的路不断移动，车内的人说着同一件事，念头却并未坐到同一个位置。", "line": "听着他们说话，路仍是一段一段地过去。死者被送去的地方，不会回答活人的疑问。", "choices": ["听车内的公开谈话", "看窗外的路与墓地"], "feedback": "同一段路上，谈话与私人记忆并排保存，没有要求你向旁人交代自己的伤痛。", "aftermath": "马车抵近墓地，仪式有其程序，思绪却会越过程序。死亡不是一道给出标准答案的题。", "kind": "sound", "items": ["车轮", "马蹄", "低声谈话"], "outro": "离开墓地，城市的工作声重新靠近。报馆里有另一种公共语言在等着你。"}, "7": {"role": "布卢姆", "portrait": "nannetti", "speaker": "南尼蒂", "title": "噪音里的广告请求", "context": "轮转机的声响填满房间。红毛穆雷剪下广告，你拿着剪报去找工长。客户要修改图样，修改意图还不是已经获准的版面。", "line": "先把要改的地方指清楚。图样与刊登条件，得分开谈。", "choices": ["以手势示意交叉的两把钥匙", "先列出待谈的业务条件"], "feedback": "南尼蒂看见了修改意图，协商仍要继续。你没有替他批准任何刊期或合同。", "aftermath": "广告业务节点告一段落。原作在报馆转向另一条人物线：斯蒂芬带来迪希的信。他不是替布卢姆办事，也还没有与布卢姆结伴。", "kind": "objects", "items": ["原剪报", "拟增补的交叉钥匙", "待议条件"], "outro": "报馆的公共谈话继续，下一幕回到布卢姆寻找午餐的街道。"}, "8": {"role": "布卢姆", "portrait": null, "speaker": "布卢姆", "title": "城市也有胃口", "context": "街道不断递来食物的气味，也递来拥挤和厌恶。走进一处饮食空间，不等于愿意在里面坐下。", "line": "换个地方。得找一个能安安静静吃点东西的地方。", "choices": ["先留意拥挤的声音", "先看食物与进食动作"], "feedback": "不合意的空间使你离开；饥饿仍在，却不是每一种喧闹都能填满它。", "aftermath": "戴维·伯恩的桌边终于有片刻停留。奶酪三明治与葡萄酒把注意拉回身体，城里的贫富处境仍在窗外。", "kind": "objects", "items": ["奶酪三明治", "葡萄酒", "街边人群"], "outro": "这次换角不表示两人同行。转去图书馆，听斯蒂芬怎样在一群人面前提出论点。"}, "9": {"role": "斯蒂芬", "portrait": null, "speaker": "斯蒂芬", "title": "说出一个论点之后", "context": "窗光落在书桌与书脊上。这里谈莎士比亚，也谈家庭、作者与作品。一个论点刚说出口，便进入别人可能赞同也可能质疑的空气里。", "line": "先把这条关系说完。论点能不能站住，还得让它经过别人的回应。", "choices": ["回看自己刚才的推论", "留意听者怎样接话"], "feedback": "你保存了论点与回应的对应关系，没有把论辩中的设想写成既定文学史。", "aftermath": "从内部看，表达带着急切；从外部看，它又可能显得锋利或故作姿态。两者不必被一句解释抹平。", "kind": "question", "items": ["提出的论点", "他人的回应", "未说出的想法"], "outro": "离开单一室内焦点。同一个时段，城市里还有许多人在走他们自己的路。"}, "10": {"role": "城市群像", "portrait": null, "speaker": "非操控叙述", "title": "同一刻，不同的街道", "context": "镜头离开单一人物。神父、街头家庭、商店与车队并置出现；这是城市的交错叙述，不是布卢姆突然知道了全城的事情。", "line": "此处没有第四位可操控主角。切换镜头，是读者的观看动作。", "choices": ["从人物往来的一端看", "从公共街道的一端看"], "feedback": "镜头之间产生照面或错过，时间并没有因为换画面而依次向前走。", "aftermath": "把几处线索放在一起，才看见城市如何在相同的时段容纳不同生活。镜头清单属于玩家记录，不属于角色共有情报。", "kind": "montage", "items": ["街头家庭", "商店与行人", "车队经过"], "outro": "街道声音逐渐聚到奥蒙德。恢复布卢姆视角，下一幕从听觉进入。"}, "11": {"role": "布卢姆", "portrait": null, "speaker": "布卢姆", "title": "听见之前，已经有回声", "context": "先有声音的碎片，然后才看清声源。女侍、车马、歌唱与钢琴不是同一条背景音，它们不断拉动你的注意。", "line": "先听清这一声从哪里来。外面的车还在走，屋里的人也有自己的曲子。", "choices": ["留意门外的车声", "留意屋里的音乐"], "feedback": "一个声音找到了人物或动作，另一个仍在远处；没有音乐也能通过文字声源完成这条路径。", "aftermath": "当片段在后文重新出现，开头的零碎便有了回声。私人不安在其中穿行，却不因此成为酒吧所有人的知识。", "kind": "sound", "items": ["车轮", "歌声", "琴键"], "outro": "另一间酒馆正有另一种声音变得尖锐。保持布卢姆身份，进入公开争执。"}, "12": {"role": "布卢姆", "portrait": "citizen", "speaker": "“市民”", "title": "门口越来越窄", "context": "谈话转到归属与身份，客套逐渐退去。你不再只是听众，对方的排斥正在冲着你来。", "line": "你说这里，究竟把谁算在里面？", "choices": ["看向正在说话的人", "留意马丁与门口的动静"], "feedback": "你按原作节点回应，敌意没有自动消失。注意选择不替换布卢姆的关键发言，也不制造辩论获胜。", "aftermath": "到达既定离场节点后，随马丁等人离开。追出、饼干罐与随后夸大的讲法分属行动及叙述层；没有躲避罐子的操作。", "kind": "layers", "items": ["现场行动", "匿名叙述", "夸饰段"], "outro": "退出酒馆。下一幕先让格蒂相关叙述占据自己的位置，再转回布卢姆。"}, "13": {"role": "格蒂相关叙述", "portrait": "gerty", "speaker": "格蒂相关叙述", "title": "两种语言看同一片海", "context": "海边的叙述先带着浪漫的陈套与格蒂相关的感受。这一段并不属于布卢姆的内心，也不让玩家操控格蒂的身体或决定。", "line": "先保留这一层语言，不急着用后来的目光替它下结论。", "choices": ["留意前段选择了哪些细节", "留意语言怎样包装场景"], "feedback": "你留下的是叙述归属，不是一份揭露人物的证据。此处角色操控暂停。", "aftermath": "原作转向布卢姆后，才恢复他的感受与判断。前段不会因此全部变成他看见、知道或能向格蒂追问的事实。", "kind": "layers", "items": ["前段语言", "转向布卢姆", "两层的差异"], "outro": "保持转向后的布卢姆路线，前往产院；身体的主题在那里换了一种现实压力。"}, "14": {"role": "布卢姆", "portrait": "nurse", "speaker": "护士", "title": "门内的辛劳，门外的谈论", "context": "你来询问产妇的情况。护理工作仍在进行，旁边的谈话却有自己的速度与姿态；两者并不因为处于同一栋楼便有同样的分量。", "line": "这里有人照料着。等一等，别让谈话挡住做事的人。", "choices": ["先留意实际的照料行动", "先听旁人怎样谈论身体"], "feedback": "你看见了工作与谈论的区别。没有进入原作未进入的病房，也没有把生产变成玩家操控的倒计时。", "aftermath": "文字自身也在变化：不同散文姿态接续出现。此处转入斯蒂芬参与的公共谈话节点，换角并不开放产妇的内心。", "kind": "layers", "items": ["护理行动", "公共谈话", "文体变化"], "outro": "人物随后转向夜街。接下来的舞台要不断区分现场与幻景。"}, "15": {"role": "布卢姆", "portrait": "bella", "speaker": "贝拉", "title": "舞台从街上长出来", "context": "气灯照着夜街，人物的话语与舞台指示交错。某个声音可以像审判一样压来，却不意味着街上真的举行了一场法庭审判。", "line": "眼前这件事得先说清楚，别让一屋子的动静盖过去。", "choices": ["看清现实中的物件与位置", "展开幻景与舞台指示"], "feedback": "你标记了一次层次转换。幻景并未写进都柏林地理档案，也不会因关闭视觉效果而丢失情节。", "aftermath": "焦点转向斯蒂芬的夜间处境；其他人物的幻景之声不增加新的可控角色。随后收回现场层，事件按原有顺序走向离场。", "kind": "layers", "items": ["现实锚点", "舞台指示", "幻景声音"], "outro": "喧闹退后，两人进入疲惫的街道。下一站先找热饮和暂歇处。"}, "16": {"role": "布卢姆", "portrait": "sailor", "speaker": "水手", "title": "一杯不像样的热饮", "context": "走了很久之后，落脚的地方未必舒适。咖啡、食物与一个水手的故事挤在同一张桌边，话语也跟着疲惫起来。", "line": "海上见过的事多了。哪一回值得讲，得看坐着的是谁。", "choices": ["先听他怎样叙述经历", "先留意眼前的饮食与疲惫"], "feedback": "说法仍是说法，记录保留了不确定性。你没有用系统资料替布卢姆当面识破一个人。", "aftermath": "布卢姆试图照料斯蒂芬，两人也仍有距离。短暂停留没有替他们完成某种必然的亲密结局。", "kind": "question", "items": ["实际行动", "水手的说法", "仍未证实的部分"], "outro": "走向埃克尔斯街。门口与厨房，将以问答重新安排两人的相似与差异。"}, "17": {"role": "布卢姆", "portrait": null, "speaker": "问答叙述", "title": "门槛与两杯可可", "context": "到了家门口，钥匙成为一件实际的小事。进屋、厨房与两杯饮品让关系靠近，问答的语言又把一切拉开，逐一比较。", "line": "哪些地方相近，哪些地方并不相同？问答可以列出它们，却不一定替两人消除距离。", "choices": ["展开共同点的一组问答", "展开差异的一组问答"], "feedback": "一处共同点与一处分歧都被留下。问答不是两人在现场互相审问，也不是玩家抢答。", "aftermath": "在斯蒂芬离去的节点，体验他的离开；随后回到布卢姆。切换不能使任何一人知道对方全部未出口的念头。", "kind": "question", "items": ["门与钥匙", "厨房与可可", "共同点与差异"], "outro": "两人的外部行动结束。最后一次换角，进入摩莉自己的意识。"}, "18": {"role": "摩莉", "portrait": null, "speaker": "摩莉", "title": "她自己的声音", "context": "归家之后，外部行动慢下来。你现在处于摩莉的意识中，记忆、欲望与眼前感受接续出现，不需要先替前面的任何人作辩护。", "line": "无需向一个外部提问者解释。字句自有回流、抵触与肯定的节奏。", "choices": ["在此处留下记忆标记", "先让意识继续流动"], "feedback": "书签属于玩家记录。它不会为摩莉增写回忆，也不把她的意识整理成一条简单的婚姻因果链。", "aftermath": "最后的收束仍依所用译本原有位置。她不是男性归家任务的奖赏，也不由一个选项决定该爱谁、原谅谁。", "kind": "memory", "items": ["当下感受", "记忆回流", "收束位置"], "outro": "回到全书地图。体验结束不等于整章原文已读，所有阅读位置仍可继续。"}};